import{_ as a,o,c as t,a5 as d}from"./chunks/framework.-jms6n7v.js";const f=JSON.parse('{"title":"Rust changelog","description":"The history of the Rust crates darudb and darudb-derive, newest first. Every package versions on its own and keeps its own history; choose another language in…","frontmatter":{"title":"Rust changelog","order":1,"editLink":false,"outline":[2,3],"prev":{"text":"Constants","link":"/types/rust/constants"},"next":{"text":"Comparison","link":"/compare"}},"headers":[{"level":2,"title":"Rust crate darudb","slug":"rust-crate-darudb","link":"#rust-crate-darudb","children":[{"level":3,"title":"darudb vNext (2026--)","slug":"darudb-vnext-2026","link":"#darudb-vnext-2026","children":[{"level":4,"title":"Changed","slug":"changed","link":"#changed","children":[]},{"level":4,"title":"Fixed","slug":"fixed","link":"#fixed","children":[]}]},{"level":3,"title":"darudb v1.1.0 (2026-10-09)","slug":"darudb-v1-1-0-2026-10-09","link":"#darudb-v1-1-0-2026-10-09","children":[{"level":4,"title":"Breaking changes","slug":"breaking-changes","link":"#breaking-changes","children":[]},{"level":4,"title":"Added","slug":"added","link":"#added","children":[]},{"level":4,"title":"Changed","slug":"changed-1","link":"#changed-1","children":[]},{"level":4,"title":"Fixed","slug":"fixed-1","link":"#fixed-1","children":[]}]},{"level":3,"title":"darudb v1.0.1 (2026-10-07)","slug":"darudb-v1-0-1-2026-10-07","link":"#darudb-v1-0-1-2026-10-07","children":[{"level":4,"title":"Fixed","slug":"fixed-2","link":"#fixed-2","children":[]}]},{"level":3,"title":"darudb v1.0.0 (2026-10-05)","slug":"darudb-v1-0-0-2026-10-05","link":"#darudb-v1-0-0-2026-10-05","children":[{"level":4,"title":"Added","slug":"added-1","link":"#added-1","children":[]}]}]},{"level":2,"title":"Rust crate darudb-derive","slug":"rust-crate-darudb-derive","link":"#rust-crate-darudb-derive","children":[{"level":3,"title":"darudb-derive v1.1.0 (2026-10-09)","slug":"darudb-derive-v1-1-0-2026-10-09","link":"#darudb-derive-v1-1-0-2026-10-09","children":[{"level":4,"title":"Changed","slug":"changed-2","link":"#changed-2","children":[]}]},{"level":3,"title":"darudb-derive v1.0.1 (2026-10-07)","slug":"darudb-derive-v1-0-1-2026-10-07","link":"#darudb-derive-v1-0-1-2026-10-07","children":[{"level":4,"title":"Changed","slug":"changed-3","link":"#changed-3","children":[]}]},{"level":3,"title":"darudb-derive v1.0.0 (2026-10-05)","slug":"darudb-derive-v1-0-0-2026-10-05","link":"#darudb-derive-v1-0-0-2026-10-05","children":[{"level":4,"title":"Added","slug":"added-2","link":"#added-2","children":[]}]}]}],"relativePath":"changelog/rust.md","filePath":"en/changelog/rust.md","lastUpdated":null}'),i={name:"changelog/rust.md"};function r(n,e,s,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="rust-changelog" tabindex="-1">Rust changelog <a class="header-anchor" href="#rust-changelog" aria-label="Permalink to &quot;Rust changelog&quot;">​</a></h1><p>The history of the Rust crates <code>darudb</code> and <code>darudb-derive</code>, newest first. Every package versions on its own and keeps its own history; choose another language in the sidebar for its packages&#39; history.</p><h2 id="rust-crate-darudb" tabindex="-1">Rust crate <code>darudb</code> <a class="header-anchor" href="#rust-crate-darudb" aria-label="Permalink to &quot;Rust crate `darudb`&quot;">​</a></h2><h3 id="darudb-vnext-2026" tabindex="-1">darudb vNext (2026--) <a class="header-anchor" href="#darudb-vnext-2026" aria-label="Permalink to &quot;darudb vNext (2026--)&quot;">​</a></h3><h4 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A sync commit on Linux, Android and the BSDs makes the file durable with <code>fdatasync</code> rather than <code>fsync</code>, which leaves out the file&#39;s times and still syncs its length with its data. A sync commit of one object takes a quarter less time for it on a GitHub-hosted Linux runner, 312 µs against 413. macOS, iOS and Windows sync as before.</li><li>A commit asks the file system for the file&#39;s length only when its record counts pages past both the published commit&#39;s and the last one the commit wrote, rather than at every commit. A deferred commit of one object takes 11% less time for it on a GitHub-hosted Linux runner, 22.3 µs against 25.1.</li></ul><h4 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>Database::backup_with</code> refuses a <code>BackupOptions::password_hashing</code> cost out of range with <code>INVALID_ARGUMENT</code> before it writes anything, as opening does, whether a password is given or not. With a password it failed with <code>INTERNAL</code>, and without one it ignored the cost.</li></ul><h3 id="darudb-v1-1-0-2026-10-09" tabindex="-1">darudb v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h4><ul><li>The file format is version 6, which earlier releases cannot open. Opening a file of version 5 raises it to version 6 while no other process has it open, so a file this release has opened no longer opens with 1.0, in Rust or in any other language&#39;s package. An application that may go back to an earlier release, or that shares its file with a program still on one, opens with <code>OpenOptions::upgrade_format(false)</code>, which also creates new files in version 5, and calls <code>Database::upgrade_format</code> once nothing older opens the file.</li></ul><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>OpenOptions::upgrade_format</code> and <code>Database::upgrade_format</code>, which say whether opening raises a file of an older format version, and raise an open one.</li></ul><h4 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>An index whose entries for one value come in key order, as a non-unique index&#39;s do while the objects&#39; primary keys grow, fills its pages as it goes, where splitting a page in the middle left half of each empty, and so do the branches of every tree. A file of 400,000 sample objects with 14 indexes is 7% smaller for it. Keys in no particular order split pages evenly, as before.</li><li><code>Database::compact</code> first writes again, full, every tree whose pages inserts left part empty, so that the file ends about as small as a backup&#39;s copy: the same file compacts to 119 MiB rather than 140 MiB. Values in overflow runs are not written again.</li><li>File format 6 writes the lengths in a leaf&#39;s entries as varints rather than in five bytes. A file of 400,000 sample objects with 14 indexes takes 8% fewer pages, 126 MiB against 138, and compacts to 110 MiB against 119, with reads and writes as fast as before. A file raised from version 5 has only its header rewritten; its leaves take the new layout as writes change them, and <code>Database::compact</code> rewrites the trees where that saves room.</li></ul><h4 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>Database::compact</code> no longer grows the file when a value in an overflow run near the file&#39;s end finds no run of free pages below to move into. The run stays where it is, and a round of moves that would grow the file is dropped.</li></ul><h3 id="darudb-v1-0-1-2026-10-07" tabindex="-1">darudb v1.0.1 (2026-10-07) <a class="header-anchor" href="#darudb-v1-0-1-2026-10-07" aria-label="Permalink to &quot;darudb v1.0.1 (2026-10-07)&quot;">​</a></h3><h4 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li>A process forked while another of its threads was opening or closing a database, or while the engine was releasing the snapshot locks it keeps for a moment, no longer hangs when it opens the file itself or ends a read transaction. The child keeps that state apart from its parent&#39;s, for up to 16 generations of processes forked one from another.</li></ul><h3 id="darudb-v1-0-0-2026-10-05" tabindex="-1">darudb v1.0.0 (2026-10-05) <a class="header-anchor" href="#darudb-v1-0-0-2026-10-05" aria-label="Permalink to &quot;darudb v1.0.0 (2026-10-05)&quot;">​</a></h3><h4 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database::open</code> and <code>OpenOptions</code> open a database file, creating it when nothing exists at the path. A new file appears whole or not at all, even when two processes create it at once. Its page size is a power of two from 4096 to 65536, and the file&#39;s header is validated every time it is opened again. The file format version is 5.</li><li><code>Database::begin_read</code> and <code>Database::begin_write</code> start transactions over named trees of byte keys and byte values. <code>ReadTransaction</code> sees one commit for as long as it lives, whatever is committed after it began. <code>WriteTransaction</code> adds <code>insert</code>, <code>remove</code> and <code>delete_tree</code>, sees its own changes, and makes all of them visible and durable at once with <code>commit</code>; dropping it aborts it. Both offer <code>get</code>, <code>range</code>, <code>range_backward</code>, <code>iter</code>, <code>len</code> and <code>tree_names</code>.</li><li>A commit is durable when <code>commit</code> returns: a crash or a power cut at any moment leaves the file at a commit no older than the last one that returned. Opening a file after a crash recovers it without a separate step.</li><li>Every page is verified against the check its parent recorded before it is used, so a damaged or stale page is reported as <code>CORRUPTED</code> rather than read.</li><li>A value too large to keep in a tree&#39;s pages is stored in pages of its own, up to 4 GiB.</li><li><code>Database</code> handles to one file in a process share one instance, so they see the same commits and take turns writing. <code>OpenOptions::busy_timeout</code> sets how long <code>begin_write</code> waits for another writer.</li><li><code>Error</code> reports every failure with a stable <code>code</code>: <code>IO</code>, <code>NOT_FOUND</code>, <code>NOT_A_DATABASE</code>, <code>UNSUPPORTED_FORMAT_VERSION</code>, <code>CORRUPTED</code>, <code>INVALID_ARGUMENT</code>, <code>CLOSED</code>, <code>BUSY</code>, <code>SYNC_FAILED</code> and <code>INTERNAL</code>. <code>CLOSED</code> is for a language binding&#39;s handle used after it was closed; <code>SYNC_FAILED</code> means a barrier failed, the last commit&#39;s outcome is unknown, and the file has to be opened again.</li><li><code>WriteTransaction::commit_deferred</code> publishes a commit without waiting for a barrier. Readers see it at once; it becomes durable at the next <code>commit</code>, at <code>Database::sync</code>, when the database is closed, or when <code>OpenOptions::max_unsynced_time</code> (one second by default) or <code>OpenOptions::max_unsynced_pages</code> runs out. The limits count the deferred commits of every process since the last barrier. A crash of the process loses no deferred commit, and a power cut undoes them only from the newest backwards. Pages that deferred commits write and stop using again are reused before the window ends once no reader needs them, so a run of small deferred commits does not grow the file.</li><li><code>Database::close</code> makes deferred commits durable first, and reports whether a barrier failed on any handle to the file.</li><li><code>OpenOptions::key</code> and <code>OpenOptions::password</code> create an encrypted database, or open one. Every page is encrypted and authenticated under a random data key, which the key, or the Argon2id hash of the password, wraps: with XAES-256-GCM on processors with AES instructions, and XChaCha20-Poly1305 elsewhere. <code>OpenOptions::password_hashing</code> sets the Argon2id cost, 19 MiB, 2 iterations and 1 lane by default.</li><li>Each commit record of an encrypted database carries a MAC under a key derived from the data key, so a record put together from the file&#39;s own pages by someone without the key is refused.</li><li><code>Database::set_key</code> and <code>Database::set_password</code> change the key of an encrypted database without encrypting any page again, and <code>Database::is_encrypted</code> tells the two kinds of database apart.</li><li>The error codes <code>KEY_REQUIRED</code>, for an encrypted database opened without a key or password, and <code>WRONG_KEY</code>, for one that does not open it.</li><li>Several processes can open one database file at once, coordinated through the operating system&#39;s byte-range locks and nothing else. One process writes at a time and <code>begin_write</code> waits for another process&#39;s writer as it does for its own, readers never wait for a writer, and a process that dies releases its locks with nothing left for the others to clean up. The first process to open a file recovers it, and one that opens it meanwhile waits up to the busy timeout. <code>Database::sync</code> makes deferred commits durable whichever process made them.</li><li>The error code <code>UNSUPPORTED_FILE_SYSTEM</code>, for a database on a network file system such as NFS or SMB, or on one whose file locks do not work. Network file systems are recognised on Linux, Android, macOS, iOS and Windows, on a best-effort basis, and a new database is refused before its file is created.</li><li>Collections of typed objects. <code>OpenOptions::schema</code> declares a <code>Schema</code> of <code>Collection</code>s, each with fields of a <code>Type</code>, a primary key that is a declared field or an auto-increment, and indexes, unique or not. The first open stores the schema in the file, and every later open compares it with the stored one. <code>ReadTransaction::collection</code> and <code>WriteTransaction::collection</code> read and write <code>Object</code>s of <code>Value</code>s: <code>insert</code>, <code>put</code>, <code>delete</code>, <code>get</code>, <code>iter</code> and <code>len</code>, with every index kept in step in the same transaction. A write the schema or a unique index refuses leaves the transaction able to commit.</li><li>Migrations. A schema carries a version, and opening a file that holds an older one migrates it in one write transaction: the engine adds collections, fields and indexes and removes what the schema no longer has, and a <code>Migration</code> registered with <code>OpenOptions::migration</code> renames collections and fields, replaces fields, deletes collections, and runs a function that moves data, reading the old objects through <code>Migrating::previous</code>.</li><li>Queries. <code>CollectionReader::query</code> and <code>CollectionWriter::query</code> return the objects a <code>Query</code> finds, and <code>count</code> counts them. A <code>Filter</code> tests fields, fields of embedded objects and fields of linked objects with comparisons, <code>between</code>, <code>is_in</code>, <code>contains</code>, <code>starts_with</code>, <code>ends_with</code> and null tests, combined with <code>and</code>, <code>or</code> and <code>!</code>; a query sorts by any number of fields and takes an offset and a limit. A condition on the primary key or an indexed field reads only the objects that meet it, and a sort on an indexed field alone stops reading at the limit. The error code <code>INVALID_QUERY</code> reports a query that names a missing field or compares a field with a value of another type.</li><li><code>Query::parse</code> reads a query written in the query language, such as <code>age &gt;= $0 AND name STARTSWITH &quot;A&quot; SORT BY age DESC LIMIT 10</code>, with parameters for <code>$0</code>, <code>$1</code> and on, into the same query the builder makes. Text that does not parse fails with <code>INVALID_QUERY</code>, naming the character where it went wrong.</li><li><code>OpenOptions::cache_size</code> sets how much memory the page cache of a file may take, in bytes: 32 MiB by default, and never fewer than 16 pages. The cache fills only as pages are read.</li><li><code>Query::prepare</code> parses a query once and keeps its parameters, and <code>Query::bind</code> gives them values, for a query that runs many times; <code>Query::bind_encoded</code> takes them encoded in one record, as a language binding sends them. A query run with a parameter that has no value fails with <code>INVALID_QUERY</code>.</li><li>The byte formats language bindings exchange with the engine: <code>CollectionReader::get_record</code>, <code>CollectionWriter::insert_record</code> and <code>put_record</code>, and <code>query_records</code> carry objects as records, which <code>get_record_with</code> and <code>query_records_with</code> lend where they lie rather than copying each into a vector; <code>QueryRequest</code> reads and writes a query as IR; <code>Database::schema_record</code> gives the stored schema as its record; and <code>Schema::decode</code> reads a schema declared in another language.</li><li><code>Query::first</code> keeps only the first object a query finds, and stops reading there.</li><li><code>OpenOptions::open_migrating</code> opens a database whose migration stops for the caller between its version steps, as a <code>PendingMigration</code>, so that a binding can run migration functions written in its own language in the migration&#39;s write transaction. <code>PendingMigration::previous_schema_record</code> and <code>Migrating::previous_record</code> give a binding the old schema and the old objects as records, and <code>PendingMigration::schema_record</code> and <code>transaction</code> the new schema and the migration&#39;s write transaction.</li><li>The error codes <code>SCHEMA_MISMATCH</code>, for a schema changed without a new version or a file migrated under an open handle, <code>SCHEMA_TOO_NEW</code>, for a file a newer application wrote, <code>DUPLICATE_KEY</code> and <code>MIGRATION_FAILED</code>. <code>UNSUPPORTED_FORMAT_VERSION</code> also reports a stored schema in an object format a newer build wrote.</li><li><code>CollectionWriter::update</code> sets the fields it is given in the object with a key and keeps the rest, going down the collection&#39;s tree once, and returns whether there was an object. The object becomes what <code>put</code> would write for the stored object with those fields set: <code>Value::Null</code> makes an optional field null and gives a field with a default its default. Changing the primary key fails with <code>INVALID_ARGUMENT</code>. <code>CollectionWriter::update_record</code> takes the changes as a record, as a language binding sends them, in which the tag <code>0x01</code> makes a field null; in a collection whose fields all hold scalars it changes the stored record where it lies and reads only the indexes on the fields it changes.</li><li><code>Database::check</code>, the integrity check: every page the published commit reaches against its check, the order of every key, every tree&#39;s count, that every page of the file is used, free or retained exactly once, and in a file with a schema every object against its indexes. It returns a <code>CheckReport</code> of every <code>Problem</code> it finds, and reads the commit a read transaction sees, so other handles and processes may write meanwhile.</li><li><code>Database::backup</code>, a copy of the published commit in a new file, written while other handles and processes go on using the database. The copy holds no free space, has the file&#39;s page size, and opens with the same key or password. It appears at the path only once it is whole and durable, and never replaces a file already there. It returns a <code>BackupReport</code>.</li><li><code>Database::backup_with</code> and <code>BackupOptions</code> write a backup under a new random data key, which a key or a password given for the copy wraps. Changing a file&#39;s key or password leaves its data key as it was, so this is how a data key that may have been exposed is left behind; a plain database&#39;s copy is encrypted the same way.</li><li><code>Database::compact</code>, which makes the file smaller in place, while other handles and processes go on using it: write transactions move the pages at the end of the file into free pages nearer its start, and the commits after them give the end back to the file system. It returns a <code>CompactReport</code>.</li><li><code>OpenOptions::salvage</code>, which rescues what it can of a damaged file into a new one. It reads the file page by page, so it works on a file that does not open, starts from the newest commit it records, and takes what that commit cannot read from older versions of the same pages where the file still has them. The new file gets its indexes built again from its objects, passes the integrity check, and opens with the same key or password. It needs the file alone, so an open file fails with <code>BUSY</code>, and it returns a <code>SalvageReport</code> of what it rescued and what it could not.</li><li>Objects as Rust types. With the <code>derive</code> feature, <code>#[derive(Object)]</code> makes a struct the objects of a collection and <code>#[derive(Embedded)]</code> makes one an embedded object, with <code>#[darudb(...)]</code> attributes for the key, indexes, field names and defaults. <code>Collection::of</code> declares the collection from the type, and <code>ReadTransaction::collection_of</code>, <code>WriteTransaction::collection_of</code> and <code>Migrating::collection_of</code> give a <code>TypedReader</code> or <code>TypedWriter</code> that reads records straight into the type and writes it as records, without building an <code>Object</code>. <code>Link&lt;T&gt;</code> is a link typed by its target. The traits <code>CollectionType</code>, <code>EmbeddedType</code>, <code>FieldType</code>, <code>ElementType</code> and <code>KeyType</code>, with <code>FieldReader</code>, <code>ValueReader</code> and <code>ValueWriter</code>, can be implemented by hand without the feature. A type whose fields do not match the stored collection fails with <code>INVALID_ARGUMENT</code>.</li></ul><h2 id="rust-crate-darudb-derive" tabindex="-1">Rust crate <code>darudb-derive</code> <a class="header-anchor" href="#rust-crate-darudb-derive" aria-label="Permalink to &quot;Rust crate `darudb-derive`&quot;">​</a></h2><h3 id="darudb-derive-v1-1-0-2026-10-09" tabindex="-1">darudb-derive v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-derive-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb-derive v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>Released together with <code>darudb</code> 1.1.0, which the code the macros generate calls and which depends on exactly this version. Nothing in the macros changed.</li></ul><h3 id="darudb-derive-v1-0-1-2026-10-07" tabindex="-1">darudb-derive v1.0.1 (2026-10-07) <a class="header-anchor" href="#darudb-derive-v1-0-1-2026-10-07" aria-label="Permalink to &quot;darudb-derive v1.0.1 (2026-10-07)&quot;">​</a></h3><h4 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>Released together with <code>darudb</code> 1.0.1, which the code the macros generate calls and which depends on exactly this version. Nothing in the macros changed.</li></ul><h3 id="darudb-derive-v1-0-0-2026-10-05" tabindex="-1">darudb-derive v1.0.0 (2026-10-05) <a class="header-anchor" href="#darudb-derive-v1-0-0-2026-10-05" aria-label="Permalink to &quot;darudb-derive v1.0.0 (2026-10-05)&quot;">​</a></h3><h4 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>#[derive(Object)]</code>, which implements <code>darudb::CollectionType</code> for a struct with named fields, and <code>#[derive(Embedded)]</code>, which implements <code>darudb::EmbeddedType</code> and <code>darudb::FieldType</code>. They read <code>#[darudb(collection = &quot;...&quot;)]</code> on the struct, and <code>key</code>, <code>index</code>, <code>unique</code>, <code>rename = &quot;...&quot;</code> and <code>default = ...</code> on a field.</li></ul>',33)])])}const g=a(i,[["render",r]]);export{f as __pageData,g as default};
